// Generated by prepare_submissions.py from submissions.json. Edit the template, then regenerate.
// Creates the submission module, its submission and section folders, their attributes, the folder derive links
// to the Table PS rows and the satisfy links from the competition process activities. Run once.
assert session.sessionResource.URI.toString().toLowerCase().contains('/fsae-2027-electric-arcadia/'): 'Only the disposable acceptance project is permitted'
assert api.layer('SA').system.summary == 'FSAE2027:bootstrap-v1': 'Missing the acceptance project marker'
def req = api.requirements()
assert req.available(): 'Install Capella Requirements Viewpoint 0.14 first'
// enableViewpoint() cannot run inside the script's transaction; the bootstrap already enabled it.
assert req.viewpointEnabled(): 'Enable the Requirements Viewpoint with the assistant action first'
assert req.find(@@MODULE_ID@@) == null: 'The submission layer already exists; run 40-verify-submissions instead of creating it again'
def modules = req.listModules().collectEntries { [(it.ReqIFIdentifier): it] }
def sourceModule = modules['FSAE-2027-V1:source-module']
assert sourceModule != null && ['FSAE2027:SD:derived-module', 'FSAE2027:DD:module', 'FSAE2027:VP:derived-module'].every { modules[it] != null }:
    'Run the bootstrap, the source import and the three safety slices first'
def sources = req.requirements(sourceModule).collectEntries { [(it.ReqIFIdentifier): it] }
assert sources.size() == 3197
def common = @@COMMON@@
def folders = @@FOLDERS@@

// One scan of OA for the two process activities; a missing or repeated name is rejected.
def wanted = folders.collectMany { it.satisfy } as Set
def elements = [:]
def iterator = api.layer('OA').eAllContents()
while (iterator.hasNext()) {
    def element = iterator.next()
    def nameFeature = element.eClass().getEStructuralFeature('name')
    if (nameFeature == null) continue
    def key = 'OA|' + element.eClass().name + '|' + element.eGet(nameFeature)
    if (wanted.contains(key)) {
        assert !elements.containsKey(key): 'Ambiguous model anchor ' + key
        elements[key] = element
    }
}
wanted.each { assert elements.containsKey(it): 'Missing model anchor ' + it }

def created = [:]
api.batch('Create the FSAE 2027 competition submission layer') {
    def module = req.createModule(api.layer('SA'), @@MODULE_ID@@, @@MODULE_TITLE@@)
    created[@@MODULE_ID@@] = module
    folders.each { spec ->
        def parent = created[spec.parent]
        assert parent != null: 'Folder parent must be created first: ' + spec.identifier
        def folder = req.createFolder(parent, spec.identifier, spec.title)
        def requirementClass = folder.eClass().getEPackage().getEClassifier('Requirement')
        assert requirementClass != null && requirementClass.isSuperTypeOf(folder.eClass()):
            'A Folder must be a Requirement subtype to carry attributes and links'
        if (spec.text) req.edit(folder, spec.title, spec.text)
        (common + spec.attributes).each { key, value -> req.setAttribute(folder, key, value) }
        spec.derive.each { id ->
            def row = sources['FSAE-2027-V1:' + id]
            assert row != null: 'Missing source paragraph FSAE-2027-V1:' + id
            req.derive(folder, row)
        }
        spec.satisfy.each { key -> req.satisfy(elements[key], folder) }
        created[spec.identifier] = folder
    }
}
assert req.requirements(created[@@MODULE_ID@@]).isEmpty()
log.info('Submission layer created: ' + (created.size() - 1) + ' folders. Run the 31-import chunks next.')
return [module: @@MODULE_ID@@, folders: created.size() - 1, items_expected: @@ITEM_COUNT@@]
